import{_ as o,o as e,c as s,S as a}from"./chunks/framework.c281b177.js";const n=JSON.parse('{"title":"Hooks 总览","description":"","frontmatter":{},"headers":[],"relativePath":"components/hooks/home.md","filePath":"components/hooks/home.md","lastUpdated":1784100367000}'),t=[a('<h1 id="hooks-总览" tabindex="-1">Hooks 总览 <a class="header-anchor" href="#hooks-总览" aria-label="Permalink to &quot;Hooks 总览&quot;">​</a></h1><h2 class="md-hidden" id="hidden-title" tabindex="-1">Hidden Title <a class="header-anchor" href="#hidden-title" aria-label="Permalink to &quot;Hidden Title {.md-hidden}&quot;">​</a></h2><p><code>hooks</code> 是基于 Vue 组合式 API 的状态和生命周期封装，适合放在 <code>sybz-components</code> 主包中使用。它们和组件一样依赖 Vue 运行环境；<code>@sybz-components/utils</code> 更适合放不依赖 Vue 的纯函数，例如格式化、校验、复制、时间处理。</p><h3 id="主流用法" tabindex="-1">主流用法 <a class="header-anchor" href="#主流用法" aria-label="Permalink to &quot;主流用法&quot;">​</a></h3><p>主流 Vue 组件库通常会把 composables/hooks 从组件库入口或独立子路径导出：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> { useLoading, usePagination } </span><span style="color:#F97583;">from</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">&#39;sybz-components&#39;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> { useLoading, usePagination } </span><span style="color:#D73A49;">from</span><span style="color:#24292E;"> </span><span style="color:#032F62;">&#39;sybz-components&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> { useLoading, usePagination } </span><span style="color:#F97583;">from</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">&#39;sybz-components/hooks&#39;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> { useLoading, usePagination } </span><span style="color:#D73A49;">from</span><span style="color:#24292E;"> </span><span style="color:#032F62;">&#39;sybz-components/hooks&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这种写法是合适的：业务项目不需要知道 hooks 的源码目录，也方便后续保持 API 稳定。建议业务侧优先从 <code>sybz-components</code> 引入；如果只想表达“我只用 hooks”，可以从 <code>sybz-components/hooks</code> 引入。</p><h3 id="当前-hooks" tabindex="-1">当前 Hooks <a class="header-anchor" href="#当前-hooks" aria-label="Permalink to &quot;当前 Hooks&quot;">​</a></h3><ul><li><a href="/sybz-components/components/hooks/useBoolean/home.html">useBoolean 布尔状态</a></li><li><a href="/sybz-components/components/hooks/useLoading/home.html">useLoading 加载状态</a></li><li><a href="/sybz-components/components/hooks/usePagination/home.html">usePagination 分页状态</a></li><li><a href="/sybz-components/components/hooks/useFlexFillSize/home.html">useFlexFillSize Flex 剩余空间尺寸</a></li><li><a href="/sybz-components/components/hooks/useEventListener/home.html">useEventListener 事件监听</a></li><li><a href="/sybz-components/components/hooks/useClickOutside/home.html">useClickOutside 外部点击</a></li></ul><h3 id="放在哪里更合适" tabindex="-1">放在哪里更合适 <a class="header-anchor" href="#放在哪里更合适" aria-label="Permalink to &quot;放在哪里更合适&quot;">​</a></h3><table><thead><tr><th>类型</th><th>推荐位置</th><th>说明</th></tr></thead><tbody><tr><td>依赖 <code>ref</code>、<code>computed</code>、生命周期、DOM 响应式监听的组合式函数</td><td><code>sybz-components/hooks</code></td><td>和 Vue 强绑定，属于组件库能力</td></tr><tr><td>纯函数、格式化、校验、数据转换</td><td><code>@sybz-components/utils</code></td><td>不依赖 Vue，更适合作为独立工具包</td></tr><tr><td>只服务组件内部的封装</td><td><code>packages/hooks</code> 内部使用</td><td>可以导出，也可以不暴露给业务</td></tr></tbody></table><p><code>useGlobalComponentConfig</code> 是组件库内部用于合并全局组件配置的 hook，业务项目通常不需要直接使用。</p>',13)],l=o({name:"components/hooks/home.md"},[["render",function(o,a,n,l,i,p){return e(),s("div",null,t)}]]);export{n as __pageData,l as default};
